INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('e0b9b3e1-2b1f-4b0e-9b1f-3b0e9b1f3b0e', 1, 'Profile Setup', 'profile-name-field', 'point', 'Enter your name', 'உங்கள் பெயரை உள்ளிடவும்', 'अपना नाम दर्ज करें', 'మీ పేరు నమోదు చేయండి', 'ನಿಮ್ಮ ಹೆಸರನ್ನು ನಮೂದಿಸಿ', 'നിങ്ങളുടെ പേര് നൽകുക', 'আপনার নাম লিখুন', 'तुमचे नाव प्रविष्ट करा', 'اپنا نام درج کریں', 'Please fill out the name field.', 'பெயர் புலத்தை நிரப்பவும்.', 'कृपया नाम फ़ील्ड भरें।', 'దయచేసి పేరు ఫీల్డ్ పూరించండి.', 'ದಯವಿಟ್ಟು ಹೆಸರು ಕ್ಷೇತ್ರವನ್ನು ಭರ್ತಿ ಮಾಡಿ.', 'ദയവായി പേര് ഫീൽഡ് പൂരിപ്പിക്കുക.', 'দয়া করে নাম ক্ষেত্রটি পূরণ করুন।', 'कृपया नाव फील्ड भरा.', 'براہ کرم نام کا فیلڈ پُر کریں۔');

INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('e0b9b3e1-2b1f-4b0e-9b1f-3b0e9b1f3b0e', 2, 'Profile Setup', 'profile-craft-type-dropdown', 'point', 'Select your craft type', 'உங்கள் கைவினை வகையைத் தேர்ந்தெடுக்கவும்', 'अपने शिल्प का प्रकार चुनें', 'మీ క్రాఫ్ట్ రకాన్ని ఎంచుకోండి', 'ನಿಮ್ಮ ಕರಕುಶಲ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆಮಾಡಿ', 'നിങ്ങളുടെ ക്രാഫ്റ്റ് തരം തിരഞ്ഞെടുക്കുക', 'আপনার শিল্পের ধরণ নির্বাচন করুন', 'तुमचा हस्तकला प्रकार निवडा', 'اپنی دستکاری کی قسم منتخب کریں', 'Please select your craft type from the list.', 'பட்டியலில் இருந்து உங்கள் கைவினை வகையைத் தேர்ந்தெடுக்கவும்.', 'कृपया सूची से अपने शिल्प का प्रकार चुनें।', 'దయచేసి జాబితా నుండి మీ క్రాఫ్ట్ రకాన్ని ఎంచుకోండి.', 'ದಯವಿಟ್ಟು ಪಟ್ಟಿಯಿಂದ ನಿಮ್ಮ ಕರಕುಶಲ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆಮಾಡಿ.', 'ലിസ്റ്റിൽ നിന്നും നിങ്ങളുടെ ക്രാഫ്റ്റ് തരം തിരഞ്ഞെടുക്കുക.', 'দয়া করে তালিকা থেকে আপনার শিল্পের ধরণ নির্বাচন করুন।', 'कृपया सूचीतून तुमचा हस्तकला प्रकार निवडा.', 'براہ کرم فہرست سے اپنی دستکاری کی قسم منتخب کریں۔');

