VALUES ('e0b9b3e1-2b1f-4b0e-9b1f-3b0e9b1f3b0e', 4, 'Profile Setup', 'profile-story-textarea', 'point', 'Tell your craft story', 'உங்கள் கைவினை கதையை சொல்லுங்கள்', 'अपनी शिल्प कहानी बताएं', 'మీ క్రాఫ్ట్ కథను చెప్పండి', 'ನಿಮ್ಮ ಕರಕುಶಲ ಕಥೆಯನ್ನು ಹೇಳಿ', 'നിങ്ങളുടെ ക്രാഫ്റ്റ് കഥ പറയുക', 'আপনার শিল্পের গল্প বলুন', 'तुमची हस्तकलेची कथा सांगा', 'اپنی دستکاری کی کہانی سنائیں', 'Please fill out your craft story.', 'உங்கள் கைவினை கதையை நிரப்பவும்.', 'कृपया अपनी शिल्प कहानी भरें।', 'దయచేసి మీ క్రాఫ్ట్ కథను పూరించండి.', 'ದಯವಿಟ್ಟು ನಿಮ್ಮ ಕರಕುಶಲ ಕಥೆಯನ್ನು ಭರ್ತಿ ಮಾಡಿ.', 'ദയവായി നിങ്ങളുടെ ക്രാഫ്റ്റ് കഥ പൂരിപ്പിക്കുക.', 'দয়া করে আপনার শিল্পের গল্প পূরণ করুন।', 'कृपया तुमची हस्तकलेची कथा भरा.', 'براہ کرم اپنی دستکاری کی کہانی پُر کریں۔');

INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('e0b9b3e1-2b1f-4b0e-9b1f-3b0e9b1f3b0e', 5, 'Profile Setup', 'profile-photo-upload', 'point', 'Add your profile photo', 'உங்கள் சுயவிவரப் புகைப்படத்தைச் சேர்க்கவும்', 'अपनी प्रोफ़ाइल फ़ोटो जोड़ें', 'మీ ప్రొఫైల్ ఫోటోను జోడించండి', 'ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಫೋಟೋ ಸೇರಿಸಿ', 'നിങ്ങളുടെ പ്രൊഫൈൽ ഫോട്ടോ ചേർക്കുക', 'আপনার প্রোফাইল ফটো যোগ করুন', 'तुमचा प्रोफाइल फोटो जोडा', 'اپنی پروفائل تصویر شامل کریں', 'Please upload a profile photo.', 'சுயவிவரப் புகைப்படத்தைப் பதிவேற்றவும்.', 'कृपया एक प्रोफ़ाइल फ़ोटो अपलोड करें।', 'దయచేసి ప్రొఫైల్ ఫోటోను అప్‌లోడ్ చేయండి.', 'ದಯವಿಟ್ಟು ಪ್ರೊಫೈಲ್ ಫೋಟೋವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.', 'ദയവായി ഒരു പ്രൊഫൈൽ ഫോട്ടോ അപ്‌ലോഡ് ചെയ്യുക.', 'দয়া করে একটি প্রোফাইল ফটো আপলোড করুন।', 'कृपया प्रोफाइल फोटो अपलोड करा.', 'براہ کرم ایک پروفائل تصویر اپ لوڈ کریں۔');

INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('e0b9b3e1-2b1f-4b0e-9b1f-3b0e9b1f3b0e', 6, 'Profile Setup', 'profile-save-button', 'point', 'Save your profile', 'உங்கள் சுயவிவரத்தை சேமிக்கவும்', 'अपनी प्रोफ़ाइल सहेजें', 'మీ ప్రొఫైల్‌ను సేవ్ చేయండి', 'ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಉಳಿಸಿ', 'നിങ്ങളുടെ പ്രൊഫൈൽ സംരക്ഷിക്കുക', 'আপনার প্রোফাইল সংরক্ষণ করুন', 'तुमचा प्रोफाइल जतन करा', 'اپنی پروفائل محفوظ کریں', 'Click the button to save your profile.', 'உங்கள் சுயவிவரத்தை சேமிக்க பொத்தானைக் கிளிக் செய்யவும்.', 'अपनी प्रोफ़ाइल सहेजने के लिए बटन पर क्लिक करें।', 'మీ ప్రొఫైల్‌ను సేవ్ చేయడానికి బటన్‌పై క్లిక్ చేయండి.', 'ನಿಮ್ಮ ಪ್ರೊಫೈಲ್ ಅನ್ನು ಉಳಿಸಲು ಬಟನ್ ಕ್ಲಿಕ್ ಮಾಡಿ.', 'നിങ്ങളുടെ പ്രൊഫൈൽ സംരക്ഷിക്കാൻ ബട്ടണിൽ ക്ലിക്കുചെയ്യുക.', 'আপনার প্রোফাইল সংরক্ষণ করতে বোতামটিতে ক্লিক করুন।', 'तुमचा प्रोफाइल जतन करण्यासाठी बटणावर क्लिक करा.', 'اپنی پروفائل محفوظ کرنے کے لیے بٹن پر کلک کریں۔');

