INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('f1c8d2f1-3c2f-4c1e-ac2f-4c1fac2f4c1f', 1, 'Dashboard', 'add-product-button', 'tap', 'Tap here to add your first product', 'உங்கள் முதல் தயாரிப்பைச் சேர்க்க இங்கே தட்டவும்', 'अपना पहला उत्पाद जोड़ने के लिए यहां टैप करें', 'మీ మొదటి ఉత్పత్తిని జోడించడానికి ఇక్కడ నొక్కండి', 'ನಿಮ್ಮ ಮೊದಲ ಉತ್ಪನ್ನವನ್ನು ಸೇರಿಸಲು ಇಲ್ಲಿ ಟ್ಯಾಪ್ ಮಾಡಿ', 'നിങ്ങളുടെ ആദ്യ ഉൽപ്പന്നം ചേർക്കാൻ ഇവിടെ ടാപ്പുചെയ്യുക', 'আপনার প্রথম পণ্য যোগ করতে এখানে আলতো চাপুন', 'तुमचे पहिले उत्पादन जोडण्यासाठी येथे टॅप करा', 'اپنی پہلی پروڈکٹ شامل کرنے کے لیے یہاں ٹیپ کریں', 'Please click the Add Product button.', 'தயாரிப்பைச் சேர் பொத்தானைக் கிளிக் செய்யவும்.', 'कृपया उत्पाद जोड़ें बटन पर क्लिक करें।', 'దయచేసి ఉత్పత్తిని జోడించు బటన్‌పై క్లిక్ చేయండి.', 'ದಯವಿಟ್ಟು ಉತ್ಪನ್ನವನ್ನು ಸೇರಿಸಿ ಬಟನ್ ಕ್ಲಿಕ್ ಮಾಡಿ.', 'ദയവായി ഉൽപ്പന്നം ചേർക്കുക ബട്ടണിൽ ക്ലിക്കുചെയ്യുക.', 'দয়া করে পণ্য যোগ করুন বোতামটিতে ক্লিক করুন।', 'कृपया उत्पादन जोडा बटणावर क्लिक करा.', 'براہ کرم پروڈکٹ شامل کریں بٹن پر کلک کریں۔');

INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('f1c8d2f1-3c2f-4c1e-ac2f-4c1fac2f4c1f', 2, 'Product Step 1', 'add-photo-button', 'tap', 'Add a clear photo of your product', 'உங்கள் தயாரிப்பின் தெளிவான புகைப்படத்தைச் சேர்க்கவும்', 'अपने उत्पाद की एक स्पष्ट तस्वीर जोड़ें', 'మీ ఉత్పత్తి యొక్క స్పష్టమైన ఫోటోను జోడించండి', 'ನಿಮ್ಮ ಉತ್ಪನ್ನದ ಸ್ಪಷ್ಟ ಫೋಟೋವನ್ನು ಸೇರಿಸಿ', 'നിങ്ങളുടെ ഉൽപ്പന്നത്തിന്റെ വ്യക്തമായ ഫോട്ടോ ചേർക്കുക', 'আপনার পণ্যের একটি পরিষ্কার ছবি যোগ করুন', 'तुमच्या उत्पादनाचा स्पष्ट फोटो जोडा', 'اپنی پروڈکٹ کی ایک واضح تصویر شامل کریں', 'Upload a product photo to proceed.', 'தொடர தயாரிப்பு புகைப்படத்தைப் பதிவேற்றவும்.', 'आगे बढ़ने के लिए उत्पाद फ़ोटो अपलोड करें।', 'కొనసాగడానికి ఉత్పత్తి ఫోటోను అప్‌లోడ్ చేయండి.', 'ಮುಂದುವರಿಯಲು ಉತ್ಪನ್ನದ ಫೋಟೋವನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.', 'തുടരുന്നതിന് ഉൽപ്പന്ന ഫോട്ടോ അപ്‌ലോഡ് ചെയ്യുക.', 'এগিয়ে যেতে পণ্যের একটি ছবি আপলোড করুন।', 'पुढे जाण्यासाठी उत्पादनाचा फोटो अपलोड करा.', 'آگے بڑھنے کے لیے پروڈکٹ کی تصویر اپ لوڈ کریں۔');

INSERT INTO guidance_steps (workflow_id, step_order, screen_name, target_id, gesture_type, instruction_en, instruction_ta, instruction_hi, instruction_te, instruction_kn, instruction_ml, instruction_bn, instruction_mr, instruction_ur, fallback_instruction_en, fallback_instruction_ta, fallback_instruction_hi, fallback_instruction_te, fallback_instruction_kn, fallback_instruction_ml, fallback_instruction_bn, fallback_instruction_mr, fallback_instruction_ur)
VALUES ('f1c8d2f1-3c2f-4c1e-ac2f-4c1fac2f4c1f', 3, 'Product Step 1 Loading', 'image-processing-loader', 'wait', 'Please wait, we are improving your photo', 'தயவுசெய்து காத்திருக்கவும், உங்கள் புகைப்படத்தை மேம்படுத்துகிறோம்', 'कृपया प्रतीक्षा करें, हम आपकी फ़ोटो को बेहतर बना रहे हैं', 'దయచేసి వేచి ఉండండి, మేము మీ ఫోటోను మెరుగుపరుస్తున్నాము', 'ದಯವಿಟ್ಟು ನಿರೀಕ್ಷಿಸಿ, ನಾವು ನಿಮ್ಮ ಫೋಟೋವನ್ನು ಸುಧಾರಿಸುತ್ತಿದ್ದೇವೆ', 'ദയവായി കാത്തിരിക്കുക, ഞങ്ങൾ നിങ്ങളുടെ ഫോട്ടോ മെച്ചപ്പെടുത്തുകയാണ്', 'অনুগ্রহ করে অপেক্ষা করুন, আমরা আপনার ছবি উন্নত করছি', 'कृपया प्रतीक्षा करा, आम्ही तुमचा फोटो सुधारत आहोत', 'براہ کرم انتظار کریں، ہم آپ کی تصویر کو بہتر بنا رہے ہیں', 'Processing photo...', 'புகைப்படத்தை செயலாக்குகிறது...', 'फ़ोटो प्रोसेस हो रही है...', 'ఫోటో ప్రాసెస్ చేయబడుతోంది...', 'ಫೋಟೋ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗುತ್ತಿದೆ...', 'ഫോട്ടോ പ്രോസസ്സ് ചെയ്യുന്നു...', 'ছবি প্রক্রিয়া করা হচ্ছে...', 'फोटोवर प्रक्रिया होत आहे...', 'تصویر پر کارروائی ہو رہی ہے...');

